if (Array.isArray(r.data) && r.data[0]) emb = Array.isArray(r.data[0]) ? r.data[0] : r.data[0].embedding;
if (!emb && r.result && Array.isArray(r.result.data) && r.result.data[0]) {
  emb = Array.isArray(r.result.data[0]) ? r.result.data[0] : r.result.data[0].embedding;
}
const ok = Array.isArray(emb) && emb.length > 0 && emb.every(x => typeof x === "number" && isFinite(x));
return { json: { embedding_ok: ok, dimensions: ok ? emb.length : 0, vecteur: ok ? "[" + emb.join(",") + "]" : "" } };

const rows = $input.all().map(i => i.json);
