const content = ((($json.choices || [])[0] || {}).message || {}).content || "";
const ctx = $('Assembler le prompt').item.json;
let reponse = "", liens = [];
const m = content.match(/\{[\s\S]*\}/);
try {
  const p = m ? JSON.parse(m[0]) : null;
  if (p && typeof p === "object") {
    reponse = String(p.reponse || "");
    liens = Array.isArray(p.liens) ? p.liens.map(String) : [];
  } else {
    reponse = content.trim();
  }
} catch (e) {
  // JSON tronqué ou invalide : on récupère le champ "reponse" s'il est lisible, sinon on ne montre jamais de JSON brut
  const r = content.match(/"reponse"\s*:\s*"((?:[^"\\]|\\.)*)/);
  reponse = r ? r[1].replace(/\\n/g, "\n").replace(/\\"/g, '"') : (content.trim().startsWith("{") ? "" : content.trim());
}
if (!reponse) reponse = "Je ne trouve pas cette information sur le site. Vous pouvez nous écrire via la page Contact : https://madeleine-riviera.fr/contact";
liens = liens.filter(u => ctx.urls.includes(u)).slice(0, 3);
if (liens.length === 0 && ctx.urls.length > 0) liens = ctx.urls.slice(0, 3);
return { json: { mode: "ia", reponse: reponse.slice(0, 1200), liens: liens } };

const q = $('Normaliser la question').item.json.question;
const STOP = ["quels","quelle","quelles","quel","comment","pour","dans","avec","vous","nous","sont","peut","puis","votre","notre","être","avoir","cette","entre","chez","aussi","faire"];
const mots = Array.from(new Set(
  q.toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(w => w.length >= 4 && !STOP.includes(w))
)).slice(0, 6);
const esc = s => s.replace(/'/g, "''");
let sql;
if (mots.length === 0) {
  sql = "SELECT titre, url, contenu FROM ia_index WHERE false";
} else {
  const arr = "ARRAY[" + mots.map(m => "'%" + esc(m) + "%'").join(",") + "]";
  sql = "SELECT titre, url, contenu FROM ia_index WHERE titre ILIKE ANY(" + arr + ") OR contenu ILIKE ANY(" + arr + ") ORDER BY (titre ILIKE ANY(" + arr + ")) DESC, titre LIMIT 5";
}
return { json: { sql: sql } };

const rows = $input.all().map(i => i.json);
const erreurRecherche = rows.some(r => r && r.error);
const lignes = rows.filter(r => r && !r.error && (r.titre || r.url));
let reponse, liens;
if (lignes.length === 0) {
  reponse = "Je ne trouve pas cette information sur le site. Vous pouvez nous écrire via la page Contact : https://madeleine-riviera.fr/contact";
  liens = ["https://madeleine-riviera.fr/contact"];
} else {
  reponse = "Voici ce que j'ai trouvé sur le site :\n" + lignes.map(r => "- " + String(r.titre || r.url || "") + (r.url ? " : " + r.url : "")).join("\n");
  liens = lignes.map(r => String(r.url || "")).filter(Boolean).slice(0, 5);
}
// Alerte au bureau seulement si le repli vient d'une vraie défaillance (IA, embedding ou base), pas d'une simple absence de résultat
const embOk = $('Extraire l\'embedding').item.json.embedding_ok === true;
const chatTentee = $('Appel Workers AI (chat)').isExecuted;
const erreurVecteur = $('Assembler le prompt').isExecuted ? $('Assembler le prompt').item.json.erreur_bdd === true : false;
const alerter = !embOk || chatTentee || erreurVecteur || erreurRecherche;
return [{ json: { mode: "simple", reponse: reponse, liens: liens, alerter: alerter }, pairedItem: { item: 0 } }];

